/**
 * LIN-4518 (P5 of LIN-4513): the comment path's two routing readers, frozen as they answered before the decision readers
 * moved to records. The goldens (tests/fixtures/walk-8/comment-path/) are what the comment path decided; they are
 * regenerated by tests/helpers/comment-path-capture.js, which must keep deciding them the way it did. So the capture reads
 * these copies, not the live route. Production reads records (lib/recommendation-blind-read.js, lib/code-routes.js); this
 * file is test-only, and P7 (LIN-4520) deletes it with lib/run-trail.js.
 *
 * What is frozen: `blindReadStepFromComments` is lib/recommendation-blind-read.js blindReadStep before LIN-4518 (the trail
 * read from comments by readTrail, the decision's advice by closeOutDecision on that trail), and `frozenRouteOf` is
 * codeRouteOf over CODE_ROUTES with exactly those two entries put back as they were: the live-stage wait without the
 * parked close-out step-aside, and the blind-read route on comments. Every other entry is the live one, unchanged.
 */
import { readTrail } from '../../lib/run-trail.js';
import { closeOutDecision } from '../../lib/run-closeout-state.js';
import { findingsNotRead } from '../../lib/close-out-findings.js';
import { isLiveRun, liveWaitOf } from '../../lib/run-live-wait.js';
import { toEpochMs } from '../../lib/utils/time.js';
import { BLIND_READ_KIND } from '../../lib/prompts/blind-read-words.js';
import { CODE_ROUTES } from '../../lib/code-routes.js';

const ATTEMPT_BOUND = 2;

/** Ended blind-read runs dispatched after `reviewAt` (ms), from the unsliced run facts (as it was before LIN-4518). */
function endedReadsSince(allRuns, reviewAt) {
  return allRuns.filter((r) => r?.stage === BLIND_READ_KIND && !isLiveRun(r)
    && (toEpochMs(r.dispatchedAt ?? r.at) ?? -Infinity) > reviewAt).length;
}

/** The blind-read route read from the comment trail, as it stood before LIN-4518. */
export function blindReadStepFromComments(issue, context = {}) {
  const comments = context.comments || [];
  const trail = readTrail(comments);
  const { routesRead } = closeOutDecision({
    trail, ticketState: issue?.state?.type ?? null, openFindings: findingsNotRead('the blind-read route reads no findings'),
  });
  if (!routesRead) return null;
  const landing = trail.landing;
  if (Array.isArray(context.allRuns)
    && endedReadsSince(context.allRuns, toEpochMs(trail.review.at) ?? -Infinity) >= ATTEMPT_BOUND) {
    return {
      step: 'blocked',
      codeRoute: 'blocked',
      why: `blind reads ended without a verdict: ${ATTEMPT_BOUND} blind-read runs ended since the latest code review approved, and no read naming ${landing.join(', ')} is on record. A person decides whether to send another or close out without one.`,
    };
  }
  return {
    step: BLIND_READ_KIND,
    codeRoute: BLIND_READ_KIND,
    why: `the latest code review approved, and no blind read since it names ${landing.join(', ')}; close-out merges only after one does, so code sends the read first.`,
  };
}

/** The route answer for one entry, as codeRouteOf read it before LIN-4518: the two changed entries frozen, the rest live. */
function frozenEntryRoute(entry, issue, context) {
  if (entry.name === 'live-wait') {
    const live = liveWaitOf(context.allRuns);
    return live ? { action: null, codeRoute: 'live-wait', wait: live.wait, why: live.why } : null;
  }
  if (entry.name === BLIND_READ_KIND) {
    const read = blindReadStepFromComments(issue, context);
    return read ? { action: read.step, codeRoute: read.codeRoute, why: read.why } : null;
  }
  return entry.route(issue, context);
}

/**
 * The code route codeRouteOf gave before LIN-4518, or null when the selector is asked.
 * @returns {{action: string|null, codeRoute: string, why: string, wait?: object}|null}
 */
export function frozenRouteOf(issue, context = {}) {
  for (const entry of CODE_ROUTES) {
    const route = frozenEntryRoute(entry, issue, context);
    if (route) return route;
  }
  return null;
}

/**
 * The route surface the goldens record (`surfaces.route`): the code route with its step and wait, or the selector's answer
 * (`close-out`, the stub's reply) when no code route applies.
 */
export function frozenSurfaceRoute(issue, context = {}, selectorAnswer = 'close-out') {
  const r = frozenRouteOf(issue, context);
  if (!r) return { codeRoute: null, recommendedAction: selectorAnswer };
  return {
    codeRoute: r.codeRoute,
    recommendedAction: r.wait ? null : r.action,
    ...(r.wait ? { liveWait: r.wait } : {}),
  };
}
